    def _compute_neighbor_fraction(self, state: np.ndarray, adj: List[List[int]], activation_rate: float) -> np.ndarray:
        # Optional sparse vectorization if SciPy is available
        try:
            from scipy.sparse import csr_matrix
            n = self.n
            rows = []
            cols = []
            data = []
            for i in range(n):
                for j in adj[i]:
                    if np.random.random() < activation_rate:
                        rows.append(i); cols.append(j); data.append(1.0)
            if not rows:
                return np.zeros(n, dtype=float)
            A = csr_matrix((data, (rows, cols)), shape=(n, n))
            neigh_sum = A.dot(state.astype(float))
            deg = np.array(A.getnnz(axis=1), dtype=float)
            with np.errstate(divide='ignore', invalid='ignore'):
                frac = np.divide(neigh_sum, deg, out=np.zeros_like(neigh_sum, dtype=float), where=deg>0)
            return frac
        except Exception:
            # Fallback to loop
            n = self.n
            frac = np.zeros(n, dtype=float)
            for i in range(n):
                neigh = adj[i]
                if not neigh:
                    frac[i] = 0.0
                    continue
                active = [j for j in neigh if np.random.random() < activation_rate]
                frac[i] = float(np.mean(state[active].astype(float))) if active else 0.0
            return frac
